import { useMutation, useQueryClient } from '@tanstack/react-query';

async function createTodo(title) {
  const res = await fetch('/api/todos', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ title }),
  });
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return res.json();
}

function AddTodo() {
  const queryClient = useQueryClient();
  const mutation = useMutation({
    mutationFn: createTodo,
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ['todos'] }),
  });

  function handleSubmit(e) {
    e.preventDefault();
    const form = e.currentTarget;
    mutation.mutate(new FormData(form).get('title'));
    form.reset();
  }

  return (
    <form onSubmit={handleSubmit}>
      <input name="title" required />
      <button disabled={mutation.isPending}>{mutation.isPending ? 'Adding…' : 'Add'}</button>
      {mutation.isError && <p role="alert">{mutation.error.message}</p>}
    </form>
  );
}

import { Suspense, use } from 'react';

const quotePromise = fetch('/api/quote').then((res) => res.json());

function Quote() {
  const quote = use(quotePromise);
  return <blockquote>{quote.text}</blockquote>;
}

export default function App() {
  return (
    <Suspense fallback={<p>Loading quote…</p>}>
      <Quote />
    </Suspense>
  );
}

